  if(choice.followups?.length)entries.push(CH(base+"-follow","어떻게 이어갈까?",choice.followups.map(f=>optionFor(topic,f,path+":"+f.key)),{condition:{variableId:"luc_t"+topic.n+"_closed",operator:"==",value:"false"}}));
  const common=(mod.fx||[]).map((row,i)=>FX(base+"-common-"+i,row));
